package com.tikuzhushou.identity;
import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.access.AccessDeniedException;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Service;
@Service public class KnowledgeBaseAccessService {private final JdbcTemplate jdbc;private final AppUserService users;public KnowledgeBaseAccessService(JdbcTemplate jdbc,AppUserService users){this.jdbc=jdbc;this.users=users;}private boolean system(){return SecurityContextHolder.getContext().getAuthentication()==null;}public UUID currentUserId(){return users.currentId(SecurityContextHolder.getContext().getAuthentication().getName());}public boolean admin(){return !system()&&SecurityContextHolder.getContext().getAuthentication().getAuthorities().stream().anyMatch(a->"ROLE_ADMIN".equals(a.getAuthority()));}public void assertKnowledgeBase(UUID id){if(system())return;UUID owner=jdbc.queryForObject("select owner_id from knowledge_bases where id=?",UUID.class,id);if(!admin()&&!owner.equals(currentUserId()))throw new AccessDeniedException("无权访问其他用户的知识库");}public void assertJob(UUID id){if(system())return;var owners=jdbc.query("select owner_id from generation_jobs where id=?",(rs,n)->rs.getObject(1,UUID.class),id);if(owners.isEmpty())throw new IllegalArgumentException("任务不存在");UUID owner=owners.getFirst();if(owner==null&&!admin())throw new AccessDeniedException("无权访问历史任务");if(owner!=null&&!admin()&&!owner.equals(currentUserId()))throw new AccessDeniedException("无权访问其他用户的任务");}public void assertDocument(UUID documentId){UUID kb=jdbc.queryForObject("select knowledge_base_id from source_documents where id=?",UUID.class,documentId);assertKnowledgeBase(kb);}}
